:root {
  --bg-ticket: #fdf6e3;
  --bg-header: #2c1e0f;
  --bg-side: #f0e8d5;
  --bg-footer: #e8dfc8;
  --accent-amber: #c8860a;
  --accent-red: #b03a2e;
  --accent-green: #2e7d52;
  --text-dark: #1a1208;
  --text-mid: #5a4020;
  --text-light: #8b6a3a;
  --text-inverse: #f5e8c8;
  --text-sub: #a08050;
  --border-main: #c8aa78;
  --dot-filled: #c8860a;
  --dot-empty: #d8c9a8;
  --status-bg: #fff3cd;
  --status-text: #7a5200;
  --warranty-bg: #2e7d52;
  --warranty-text: #e8f5ee;
  --part-alt: #b03a2e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.ticket {
  width: 470px;
  background: var(--bg-ticket);
  border: 2px solid var(--border-main);
  border-radius: 8px;
  overflow: hidden;
  font-size: 12px;
}

.ticket-header {
  background: var(--bg-header);
  padding: 9px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.shop-icon {
  font-size: 24px;
  line-height: 1;
}

.shop-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.shop-name {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-inverse);
  letter-spacing: 0.3px;
}

.shop-sub {
  font-size: 9px;
  color: var(--accent-amber);
  font-weight: 600;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.ticket-id {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0px;
}

.id-label {
  font-size: 9px;
  color: var(--text-sub);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.id-num {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-amber);
  letter-spacing: 1px;
}

.ticket-body {
  display: flex;
}

.col-main {
  flex: 1;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 9px;
  border-right: 1px dashed var(--border-main);
}

.col-side {
  width: 130px;
  background: var(--bg-side);
  padding: 10px 11px;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.device-block,
.issue-block,
.parts-list,
.tech-block,
.status-block,
.priority-block,
.estimate-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.device-label,
.issue-label,
.parts-label,
.tech-label,
.status-label,
.priority-label,
.est-label {
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-light);
  font-weight: 700;
}

.device-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-dark);
}

.device-model {
  font-size: 10px;
  color: var(--text-mid);
}

.issue-text {
  font-size: 10px;
  color: var(--text-mid);
  line-height: 1.45;
}

.parts {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 0;
}

.part-item {
  font-size: 10px;
  color: var(--text-dark);
  display: flex;
  align-items: center;
  gap: 5px;
}

.part-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-amber);
  flex-shrink: 0;
}

.part-dot.alt {
  background: var(--part-alt);
}

.tech-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-dark);
}

.tech-cert {
  font-size: 9px;
  color: var(--text-light);
  font-style: italic;
}

.status-badge {
  display: inline-block;
  background: var(--status-bg);
  color: var(--status-text);
  font-size: 9px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 3px;
  border: 1px solid var(--accent-amber);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  align-self: flex-start;
}

.priority-dots {
  display: flex;
  gap: 3px;
  align-items: center;
  flex-wrap: wrap;
}

.dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--dot-empty);
}

.dot.filled {
  background: var(--dot-filled);
}

.priority-text {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-red);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-left: 2px;
}

.est-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--accent-amber);
}

.ticket-footer {
  background: var(--bg-footer);
  border-top: 1px dashed var(--border-main);
  padding: 8px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-dates {
  display: flex;
  align-items: center;
  gap: 8px;
}

.date-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.date-label {
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: var(--text-light);
  font-weight: 700;
}

.date-val {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-dark);
}

.date-sep {
  font-size: 12px;
  color: var(--accent-amber);
  font-weight: 700;
  margin-top: 6px;
}

.warranty-badge {
  background: var(--warranty-bg);
  color: var(--warranty-text);
  font-size: 9px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
